  const getBasePrice = useCallback(
    (productId: string, variantId?: string): number => {
      const product = products.find((p) => String(p.id) === String(productId));
      if (!product) return 0;
      if (variantId) {
        const variant = product.variants?.find((v) => String(v.id) === String(variantId));
        if (variant) return variant.sellingPrice ?? product.sellingPrice ?? 0;
      }
      return product.sellingPrice ?? 0;
    },
    [products]
  );

  const getPriceListPrice = useCallback(
    (productId: string, variantId?: string): number | null => {
      if (!defaultPriceList) return null;
      // Find item override: first try variant-specific, then base product (null variant)
      let item = defaultPriceList.items.find(
        (item) => String(item.productId) === String(productId) && variantId && String(item.variantId) === String(variantId)
      );
      if (!item) {
        item = defaultPriceList.items.find(
          (item) => String(item.productId) === String(productId) && !item.variantId
        );
      }
      if (item) {
        if (item.sellingPrice != null) return item.sellingPrice;
        if (item.discountPercentage != null && item.discountPercentage > 0) {
          const base = getBasePrice(productId, variantId);
          return base * (1 - item.discountPercentage / 100);
        }
      }
      // No override, use global discount
      if (defaultPriceList.discountPercentage > 0) {
        const base = getBasePrice(productId, variantId);
        return base * (1 - defaultPriceList.discountPercentage / 100);
      }
      return null;
    },
    [defaultPriceList, getBasePrice]
  );

