        gstNumber: fetchedSettings.gst_number || fetchedSettings.gstNumber || '',
        billPrefix: fetchedSettings.bill_prefix || fetchedSettings.billPrefix || 'INV',
        shopLogoUrl: fetchedSettings.shop_logo_url,
