  }, [fetchedSettings, settingsLoading]);

  // Auto-detect interstate based on customer state vs shop state
  useEffect(() => {
    if (customer.stateCode && posSettings.stateCode) {
      const isDifferentState = customer.stateCode !== posSettings.stateCode;
