  });
  const [billCounter, setBillCounter] = useState(() => {
    const stored = localStorage.getItem('bill_counter');
    return stored ? parseInt(stored) : 41;
  });
  const [nextInvoiceNumber, setNextInvoiceNumber] = useState<string>('');

  const [showBillQR, setShowBillQR] = useState(false);
  const [billQRData, setBillQRData] = useState<{ value: string; title: string }>({ value: '', title: '' });

  const [showBillBarcode, setShowBillBarcode] = useState(false);
  const [billBarcodeData, setBillBarcodeData] = useState<{ value: string; title: string }>({ value: '', title: '' });

  const [showPdfPreview, setShowPdfPreview] = useState(false);
  const [createdInvoiceForPreview, setCreatedInvoiceForPreview] = useState<any>(null);

  const [showScanner, setShowScanner] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Serial Number Tracking
  const [showSerialModal, setShowSerialModal] = useState(false);
  const [serialProduct, setSerialProduct] = useState<any>(null);
  const [serialNumbers, setSerialNumbers] = useState<string[]>([]);
  const [serialInput, setSerialInput] = useState('');

  // Batch Tracking
  const [showBatchModal, setShowBatchModal] = useState(false);
  const [batchProduct, setBatchProduct] = useState<any>(null);
  const [batchInfo, setBatchInfo] = useState<{ batchNumber: string; quantity: number; expiryDate?: string }>({ batchNumber: '', quantity: 1 });

  // Manual Mode - for adding custom items without product lookup
  const [manualMode, setManualMode] = useState(false);
  const [showManualItemModal, setShowManualItemModal] = useState(false);
  const [manualItemForm, setManualItemForm] = useState({
    name: '',
    price: 0,
    quantity: 1,
    gstRate: 0,
    primaryUnitId: '',
    secondaryUnitId: '',
    conversionFactor: 1,
  });

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ignore if typing in input fields
      const target = e.target as HTMLElement;
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.tagName === 'SELECT') {
        return;
      }

      const key = e.key.toLowerCase();
      const ctrl = e.ctrlKey || e.metaKey;

      // Ctrl/Cmd + N - New Bill / Clear Cart
      if (ctrl && key === 'n') {
        e.preventDefault();
        if (cart.length > 0) {
          showAlert({
            title: 'Clear Cart?',
            message: 'This will remove all items from the cart. Continue?',
            type: 'warning',
            onConfirm: () => {
              setCart([]);
              setCustomer({ name: '', mobile: '' });
              setOverallDiscount(0);
              setRemarks('');
              setPointsToRedeem(0);
              setLoyaltyDiscount(0);
              setAppliedBundle(null);
              showToast('Cart cleared', 'success');
