      }

      // Ctrl/Cmd + K - Focus customer search
      if (ctrl && key === 'k') {
        e.preventDefault();
        const searchInput = document.getElementById('customer-search');
        if (searchInput) {
          (searchInput as HTMLInputElement).focus();
        }
      }

      // Ctrl/Cmd + P - Quick Print (if cart has items)
      if (ctrl && key === 'p') {
        e.preventDefault();
        if (cart.length > 0 && typeof handleCreateBill === 'function') {
          handleCreateBill();
        }
      }

      // Ctrl/Cmd + Q - Open Scanner
      if (ctrl && key === 'q') {
        e.preventDefault();
        setShowScanner(true);
      }

      // Ctrl/Cmd + M - Manual item mode
      if (ctrl && key === 'm') {
        e.preventDefault();
        setShowManualItemModal(true);
      }

      // Escape - Clear search / Close modals
      if (key === 'escape') {
        if (showScanner) setShowScanner(false);
        if (showBillQR) setShowBillQR(false);
        if (showBillBarcode) setShowBillBarcode(false);
        if (showManualItemModal) setShowManualItemModal(false);
        if (showSerialModal) setShowSerialModal(false);
        if (showBatchModal) setShowBatchModal(false);
        if (searchTerm) setSearchTerm('');
      }

      // F1 - Focus product search
      if (key === 'f1') {
        e.preventDefault();
        const productSearch = document.getElementById('product-search');
        if (productSearch) {
          (productSearch as HTMLInputElement).focus();
        }
      }

      // F2 - Focus amount received
      if (key === 'f2') {
        e.preventDefault();
        const amountInput = document.getElementById('amount-received');
        if (amountInput) {
          (amountInput as HTMLInputElement).focus();
          (amountInput as HTMLInputElement).select();
        }
      }

      // F3 - Show/hide QR code
      if (key === 'f3') {
        e.preventDefault();
        if (cart.length > 0) {
          setShowBillQR(!showBillQR);
        }
      }

      // F4 - Toggle manual mode
      if (key === 'f4') {
        e.preventDefault();
        setManualMode(!manualMode);
        showToast(manualMode ? 'Manual mode disabled' : 'Manual mode enabled', 'info');
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [cart, showScanner, showBillQR, showBillBarcode, showManualItemModal, showSerialModal, showBatchModal, searchTerm, manualMode, customer]);

  // Auto-Scan Listener for Hardware Barcode Scanners
  const scanBuffer = useRef('');
  const lastKeyTime = useRef(Date.now());

  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      // Ignore input if the user is explicitly typing in an input field or textarea
      const target = e.target as HTMLElement;
      if (
        !target ||
        target.tagName === 'INPUT' ||
        target.tagName === 'TEXTAREA' ||
        target.isContentEditable
      ) {
        return;
      }

      const currentTime = Date.now();
      const timeDiff = currentTime - lastKeyTime.current;

      // Scanners type fast (typically < 30ms between strokes). 
      // If the gap is larger than 50ms, assume it's human typing and reset.
      if (timeDiff > 50) {
        scanBuffer.current = '';
      }

      // If Enter is pressed and buffer is long enough, process it
      if (e.key === 'Enter') {
        if (scanBuffer.current.length > 3) {
          e.preventDefault();
          const codeToProcess = scanBuffer.current;
          scanBuffer.current = ''; // Reset Buffer

          // Trigger the scan handler
          const handled = processScannedCode(codeToProcess);
          if (!handled) {
            showToast('Product not found for scanned code', 'error');
          }
        }
      } else if (e.key.length === 1) {
        // Collect standard characters
        scanBuffer.current += e.key;
      }

      lastKeyTime.current = currentTime;
    };

    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [products]);



  const searchResults = useMemo(() => {
    if (!searchTerm) return [];

    const results: any[] = [];
    const term = searchTerm.toLowerCase();

    // Check if search term looks like a UPC number (11-12 digits, spaces stripped for copy-pasted barcodes)
    const strippedTerm = searchTerm.replace(/\s+/g, '');
    const isUPCSearch = /^\d{11,12}$/.test(strippedTerm);
    const normalizedUPC = isUPCSearch
      ? (strippedTerm.length === 12 ? strippedTerm : upcCheckDigit(strippedTerm))
      : '';

    products.forEach((p) => {
      const nameMatch = p.name.toLowerCase().includes(term);
      const skuMatch = p.sku.toLowerCase().includes(term);
      const barcodeMatch = (p.barcode || '').toLowerCase().includes(term);
      const upcMatch = isUPCSearch && skuToFullUPC(p.sku) === normalizedUPC;
      const match = nameMatch || skuMatch || barcodeMatch || upcMatch;

      if (match) {
        if (p.isVariantProduct) {
          // If it's a UPC match at product level, show all variants
          const showAll = upcMatch || nameMatch;
          p.variants.forEach((v) => {
            const variantUpcMatch = isUPCSearch && skuToFullUPC(v.sku) === normalizedUPC;
            const variantBarcodeMatch = (v.barcode || '').toLowerCase().includes(term);
            if (
              showAll ||
              variantUpcMatch ||
              v.sku.toLowerCase().includes(term) ||
              variantBarcodeMatch
            ) {
              results.push({
                ...p,
                isVariantEntry: true,
                variant: v,
                displayName: `${p.name} (${v.color} / ${v.size})`,
                displaySku: v.sku,
                displayPrice: getPriceListPrice(p.id, v.id) ?? v.sellingPrice,
                displayStock: v.currentStock,
                barcode: v.barcode || p.barcode,
                trackingType: p.trackingType,
              });
            }
          });
        } else {
          results.push({
            ...p,
            isVariantEntry: false,
            displayName: p.name,
            displaySku: p.sku,
            displayPrice: getPriceListPrice(p.id) ?? p.sellingPrice,
            displayStock: p.currentStock,
            barcode: p.barcode,
            trackingType: p.trackingType,
          });
        }
      }
    });

    return results.slice(0, 8);
  }, [searchTerm, products, getPriceListPrice]);

  const addToCart = async (item: any, serials?: string[], batchNum?: string, expiryDate?: string) => {
    const productId = item.id;
    const variantId = item.isVariantEntry ? item.variant.id : undefined;

    // Check if serial tracking is enabled
    if (!serials && item.trackingType === 'serial') {
      setSerialProduct(item);
      setSerialNumbers([]);
      setSerialInput('');
      setShowSerialModal(true);
      return;
    }

    // Check if batch tracking is enabled
    if (!batchNum && item.trackingType === 'batch') {
      setBatchProduct(item);
      setBatchInfo({ batchNumber: '', quantity: item.displayStock || 1 });
      setShowBatchModal(true);
      return;
    }

    // Resolve dynamic price if pricing rules or price lists are active
    const hasPricing = pricingRules.length > 0 || priceLists.length > 0;
    let resolvedPrice = item.displayPrice;
    let priceSource = 'default';
    let priceSourceName = undefined;

    if (hasPricing) {
      try {
        const resolution = await pricingApi.resolvePrice({
          productId,
          variantId,
          quantity: 1,
          customerId: customer?.id,
          priceListId: defaultPriceListId,
        });
        if (resolution.price > 0) {
          resolvedPrice = resolution.price;
          priceSource = resolution.source;
          priceSourceName = resolution.appliedRuleName;
        }
      } catch (error) {
        console.error('Failed to resolve price:', error);
        // Fall back to default price on error
      }
    }

    setCart((prev) => {
      const existing = prev.find(
        (i) => i.productId === productId && i.variantId === variantId && i.unitPrice === resolvedPrice,
      );

      let qtyToAdd = 1;
      let mergedSerials = existing?.serialNumbers || [];

      if (serials && serials.length > 0) {
        if (existing) {
          const newUniqueSerials = serials.filter(s => !mergedSerials.includes(s));
          if (newUniqueSerials.length === 0) return prev; // All provided serials are duplicates
          qtyToAdd = newUniqueSerials.length;
          mergedSerials = [...mergedSerials, ...newUniqueSerials];
        } else {
          qtyToAdd = serials.length;
          mergedSerials = [...serials];
        }
      }

      if (existing) {
        return prev.map((i) =>
          i.productId === productId && i.variantId === variantId && i.unitPrice === resolvedPrice
            ? {
                ...i,
                quantity: i.quantity + qtyToAdd,
                total: (i.quantity + qtyToAdd) * i.unitPrice - i.discount,
                serialNumbers: serials ? mergedSerials : i.serialNumbers,
              }
            : i,
        );
      }
      return [
        ...prev,
        {
          cartItemId: generateCartItemId(),
          productId,
          variantId,
          name: item.displayName,
          quantity: qtyToAdd,
          unitPrice: resolvedPrice,
          discount: 0,
          total: qtyToAdd * resolvedPrice,
          serialNumbers: serials && serials.length > 0 ? mergedSerials : undefined,
          batchNumber: batchNum,
          expiryDate: expiryDate,
          gstRate: item.gstRate,
          priceSource,
          priceSourceName,
          manualOverride: false,
        },
      ];
    });
    setSearchTerm('');
  };

  // Add a manually entered item to cart (no product lookup)
  const addManualItem = (
    name: string,
    price: number,
    quantity: number,
    gstRate: number = 0,
    primaryUnit?: { id: string; name: string; symbol: string },
    secondaryUnit?: { id: string; name: string; symbol: string },
    conversionFactor?: number
  ) => {
    if (!name.trim() || price <= 0 || quantity <= 0) {
      showToast('Please enter valid item details', 'error');
      return;
    }

    setCart((prev) => [
      ...prev,
      {
        cartItemId: generateCartItemId(),
        productId: 'manual-' + Date.now() + '-' + Math.random().toString(36).slice(2, 9),
        variantId: undefined,
        name: name.trim(),
        quantity,
        unitPrice: price,
        discount: 0,
        total: quantity * price,
        gstRate,
        priceSource: 'manual',
        priceSourceName: 'Manual Entry',
        manualOverride: true,
        isManualItem: true,
        primaryUnit,
        secondaryUnit,
        conversionFactor,
        unit: primaryUnit?.symbol,
      },
    ]);

    showToast(`Added "${name}" to cart`, 'success');
    setShowManualItemModal(false);
    setManualItemForm({ name: '', price: 0, quantity: 1, gstRate: 0, primaryUnitId: '', secondaryUnitId: '', conversionFactor: 1 });
  };

  const handleAddToCartWithSerial = () => {
    if (serialProduct && serialNumbers.length > 0) {
      addToCart(serialProduct, serialNumbers);
      setShowSerialModal(false);
      setSerialNumbers([]);
      setSerialInput('');
      setSerialProduct(null);
      showToast(`Added ${serialProduct.displayName} to cart`, 'success');
    }
  };

  const addSerialNumber = () => {
    if (serialInput.trim() && serialNumbers.length < (serialProduct?.quantity || 999)) {
      setSerialNumbers([...serialNumbers, serialInput.trim().toUpperCase()]);
      setSerialInput('');
    }
  };

  const removeSerialNumber = (index: number) => {
    setSerialNumbers(serialNumbers.filter((_, i) => i !== index));
  };

  const processScannedCode = (code: string): boolean => {
    if (!code) return false;
    // Strip spaces so copy-pasted UPC-A codes like '0 00000 00022 2' work correctly
    const cleanCode = code.trim().replace(/\s+/g, '');

    // 0. Check for weighted barcode (Supermarket Method)
    // Structure: 29 (prefix) + 5 digit product code + 5 digit price + 1 check digit
    if (cleanCode.length === 13 && cleanCode.startsWith('29')) {
      const productCode = cleanCode.substring(2, 7);
      const priceString = cleanCode.substring(7, 12);
      const extractedPrice = parseFloat(priceString);

      const exactMatch = products?.find(p => p.sku.trim() === productCode);
      if (exactMatch) {
        addToCart({
          ...exactMatch,
          isVariantEntry: false,
          displayName: exactMatch.name,
          displaySku: exactMatch.sku,
          displayPrice: extractedPrice,
          displayStock: exactMatch.currentStock,
          trackingType: exactMatch.trackingType,
        });
        showToast(`Added ${exactMatch.name} to cart (Weighted)`, 'success');
        return true;
      }

      for (const p of products || []) {
        if (p.isVariantProduct) {
          const variant = p.variants?.find(v => v.sku.trim() === productCode);
          if (variant) {
            addToCart({
              ...p,
              isVariantEntry: true,
              variant: variant,
              displayName: `${p.name} (${variant.color} / ${variant.size})`,
              displaySku: variant.sku,
              displayPrice: extractedPrice,
              displayStock: variant.currentStock,
              trackingType: p.trackingType,
            });
            showToast(`Added ${p.name} to cart (Weighted)`, 'success');
            return true;
          }
        }
      }
    }

    // 1. Try exact SKU match first
    const exactMatch = products?.find(p => p.sku.trim().toLowerCase() === cleanCode.toLowerCase());
    if (exactMatch) {
      addToCart({
        ...exactMatch,
        isVariantEntry: false,
        displayName: exactMatch.name,
        displaySku: exactMatch.sku,
        displayPrice: exactMatch.sellingPrice,
        displayStock: exactMatch.currentStock,
        trackingType: exactMatch.trackingType,
      });
      showToast(`Added ${exactMatch.name} to cart`, 'success');
      return true;
    }

    // 1b. Try exact product barcode match
    const exactBarcodeMatch = products?.find(p => (p.barcode || '').trim().toLowerCase() === cleanCode.toLowerCase());
    if (exactBarcodeMatch) {
      addToCart({
        ...exactBarcodeMatch,
        isVariantEntry: false,
        displayName: exactBarcodeMatch.name,
        displaySku: exactBarcodeMatch.sku,
        displayPrice: exactBarcodeMatch.sellingPrice,
        displayStock: exactBarcodeMatch.currentStock,
        trackingType: exactBarcodeMatch.trackingType,
      });
      showToast(`Added ${exactBarcodeMatch.name} to cart`, 'success');
      return true;
    }

    // 1c. Try exact variant barcode match
    for (const product of products) {
      if (!product.isVariantProduct) continue;
      const matchedVariant = product.variants.find((variant) => (variant.barcode || '').trim().toLowerCase() === cleanCode.toLowerCase());
      if (matchedVariant) {
        addToCart({
          ...product,
          isVariantEntry: true,
          variant: matchedVariant,
          displayName: `${product.name} (${matchedVariant.color} / ${matchedVariant.size})`,
          displaySku: matchedVariant.sku,
          displayPrice: matchedVariant.sellingPrice,
          displayStock: matchedVariant.currentStock,
          barcode: matchedVariant.barcode || product.barcode,
          trackingType: product.trackingType,
        });
        showToast(`Added ${product.name} to cart`, 'success');
        return true;
      }
    }

    // 2. Try exact variant SKU match
    for (const p of products) {
      if (p.isVariantProduct) {
        const variant = p.variants.find(v => v.sku.trim().toLowerCase() === cleanCode.toLowerCase());
        if (variant) {
          addToCart({
            ...p,
            isVariantEntry: true,
            variant: variant,
            displayName: `${p.name} (${variant.color} / ${variant.size})`,
            displaySku: variant.sku,
            displayPrice: variant.sellingPrice,
            displayStock: variant.currentStock,
            trackingType: p.trackingType,
          });
          showToast(`Added ${p.name} to cart`, 'success');
          return true;
        }
      }
    }

    // 3. Try UPC-A reverse lookup (for files exported from BarcodeGenerator / BulkBarcodeSheet)
    // Normalise input: if 11 digits, append check digit; if 12 digits use as-is
    const isAllDigits = /^\d+$/.test(cleanCode);
    if (isAllDigits && (cleanCode.length === 11 || cleanCode.length === 12)) {
      const normalizedUPC = cleanCode.length === 11 ? skuToFullUPC(cleanCode) : cleanCode;

      const upcProductMatch = products?.find(p => skuToFullUPC(p.sku) === normalizedUPC);
      if (upcProductMatch) {
        addToCart({
          ...upcProductMatch,
          isVariantEntry: false,
          displayName: upcProductMatch.name,
          displaySku: upcProductMatch.sku,
          displayPrice: upcProductMatch.sellingPrice,
          displayStock: upcProductMatch.currentStock,
          trackingType: upcProductMatch.trackingType,
        });
        showToast(`Added ${upcProductMatch.name} to cart`, 'success');
        return true;
      }

      for (const p of products) {
        if (p.isVariantProduct) {
          const variant = p.variants.find(v => skuToFullUPC(v.sku) === normalizedUPC);
          if (variant) {
            addToCart({
              ...p,
              isVariantEntry: true,
              variant: variant,
              displayName: `${p.name} (${variant.color} / ${variant.size})`,
              displaySku: variant.sku,
              displayPrice: variant.sellingPrice,
              displayStock: variant.currentStock,
              trackingType: p.trackingType,
            });
            showToast(`Added ${p.name} to cart`, 'success');
            return true;
          }
        }
      }
    }

    // 4. Try hyphenated serialized code matching `<SKU>-<SUFFIX>`
    const lastHyphenIndex = cleanCode.lastIndexOf('-');
    if (lastHyphenIndex !== -1) {
      const baseSku = cleanCode.substring(0, lastHyphenIndex).trim();
      const serialSuffix = cleanCode.substring(lastHyphenIndex + 1).trim();

      // check normal product
      const baseMatch = products?.find(p => p.sku.trim().toLowerCase() === baseSku.toLowerCase() && p.trackingType?.toLowerCase() === 'serial');
      if (baseMatch) {
        addToCart({
          ...baseMatch,
          isVariantEntry: false,
          displayName: baseMatch.name,
          displaySku: baseMatch.sku,
          displayPrice: baseMatch.sellingPrice,
          displayStock: baseMatch.currentStock,
          trackingType: baseMatch.trackingType,
        }, [serialSuffix]);
        showToast(`Added ${baseMatch.name} (S/N: ${serialSuffix}) to cart`, 'success');
        return true;
      }

      // check variant base
      for (const p of products) {
        if (p.isVariantProduct && p.trackingType?.toLowerCase() === 'serial') {
          const variant = p.variants.find(v => v.sku.trim().toLowerCase() === baseSku.toLowerCase());
          if (variant) {
            addToCart({
              ...p,
              isVariantEntry: true,
              variant: variant,
              displayName: `${p.name} (${variant.color} / ${variant.size})`,
              displaySku: variant.sku,
              displayPrice: variant.sellingPrice,
              displayStock: variant.currentStock,
              trackingType: p.trackingType,
            }, [serialSuffix]);
            showToast(`Added ${p.name} (S/N: ${serialSuffix}) to cart`, 'success');
            return true;
          }
        }
      }
    }

    return false;
  };

  const handleScanResult = (result: string | null) => {
    if (result) {
      setSearchTerm(result);
      setShowScanner(false);
      const handled = processScannedCode(result);
      if (!handled) {
        showToast('Product not found for scanned code', 'error');
      }
    }
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;

      // Split by common delimiters: newline, comma, carriage return, semicolon
      const rawCodes = text.split(/[\n\r,;]+/);
      let successCount = 0;
      let failCount = 0;

      rawCodes.forEach(rawCode => {
        // Remove quotes, non-printable characters, and trim whitespace
        const cleaned = rawCode.replace(/[\u200B-\u200D\uFEFF\u0000-\u001F\u007F-\u009F]/g, '').replace(/["']/g, '').trim();
        if (cleaned) {
          const handled = processScannedCode(cleaned);
          if (handled) {
            successCount++;
          } else {
            failCount++;
          }
        }
      });

      if (successCount > 0) {
        showAlert({
          title: 'Upload Successful',
          message: `Successfully processed ${successCount} item(s) from the file.${failCount > 0 ? ` Note: ${failCount} item(s) could not be found.` : ''}`,
          type: 'success'
        });
      } else {
        showAlert({
          title: 'Upload Failed',
          message: `Could not find any matching products from the file. (${failCount} barcodes parsed)`,
          type: 'error'
        });
      }
    };
    reader.readAsText(file);
    // Reset input so the same file can be uploaded again if needed
    event.target.value = '';
  };


  const updateQuantity = async (
    productId: string,
    variantId: string | undefined,
    unitPrice: number,
    delta: number,
  ) => {
    const hasPricing = pricingRules.length > 0 || priceLists.length > 0;

    // Find the item to check for manual override
    const cartItem = cart.find(i => i.productId === productId && i.variantId === variantId && i.unitPrice === unitPrice);
    if (!cartItem) return;

    const newQty = Math.max(1, cartItem.quantity + delta);

    // Recalculate price if pricing exists, not manually overridden, AND not in manual mode
    const shouldRecalculate = hasPricing && !cartItem.manualOverride && !manualMode && !cartItem.isManualItem;

    if (shouldRecalculate) {
      try {
        const resolution = await pricingApi.resolvePrice({
          productId,
          variantId,
          quantity: newQty,
          customerId: customer?.id,
          priceListId: defaultPriceListId,
        });

        // Update cart with new quantity and potentially new price
        setCart((current) => current.map((i) => {
          if (i.productId === productId && i.variantId === variantId && i.unitPrice === unitPrice) {
            const newPrice = resolution.price > 0 ? resolution.price : i.unitPrice;
            return {
              ...i,
              quantity: newQty,
              unitPrice: newPrice,
              total: newQty * newPrice - i.discount,
              priceSource: resolution.source,
              priceSourceName: resolution.appliedRuleName,
            };
          }
          return i;
        }));
      } catch (error) {
        console.error('Failed to recalculate price:', error);
        // On error, just update quantity with existing price
        setCart((current) => current.map((i) => {
          if (i.productId === productId && i.variantId === variantId && i.unitPrice === unitPrice) {
            return {
              ...i,
              quantity: newQty,
              total: newQty * i.unitPrice - i.discount,
            };
          }
          return i;
        }));
      }
    } else {
      // No pricing rules or manual override - just update quantity
      setCart((current) => current.map((i) => {
        if (i.productId === productId && i.variantId === variantId && i.unitPrice === unitPrice) {
          return {
            ...i,
            quantity: newQty,
            total: newQty * i.unitPrice - i.discount,
          };
        }
        return i;
      }));
    }
  };

  const updateDiscount = (
    productId: string,
    variantId: string | undefined,
    unitPrice: number,
    discount: number,
  ) => {
    setCart((prev) =>
      prev.map((item) => {
        if (item.productId === productId && item.variantId === variantId && item.unitPrice === unitPrice) {
          const safeDiscount = Math.max(
            0,
            Math.min(discount, item.quantity * item.unitPrice),
          );
          return {
            ...item,
            discount: safeDiscount,
            total: item.quantity * item.unitPrice - safeDiscount,
          };
        }
        return item;
      }),
    );
  };

  const removeFromCart = (productId: string, variantId: string | undefined, unitPrice: number) => {
    setCart((prev) =>
      prev.filter(
        (item) => !(item.productId === productId && item.variantId === variantId && item.unitPrice === unitPrice),
      ),
    );
  };

  // Manual price override - allows user to set custom price for an item
  const updateManualPrice = (
    productId: string,
    variantId: string | undefined,
    oldUnitPrice: number,
    newUnitPrice: number,
  ) => {
    setCart((prev) =>
      prev.map((item) => {
        if (item.productId === productId && item.variantId === variantId && item.unitPrice === oldUnitPrice) {
          const safePrice = Math.max(0, newUnitPrice);
          return {
            ...item,
            unitPrice: safePrice,
            total: item.quantity * safePrice - item.discount,
            manualOverride: true,
            priceSource: 'manual',
            priceSourceName: 'Manual Override',
          };
        }
        return item;
      }),
    );
  };

  // Reset price to system-calculated value
  const resetToSystemPrice = async (
    productId: string,
    variantId: string | undefined,
    unitPrice: number,
  ) => {
    const hasPricing = pricingRules.length > 0 || priceLists.length > 0;
    if (!hasPricing) return;

    try {
      const cartItem = cart.find(i => i.productId === productId && i.variantId === variantId && i.unitPrice === unitPrice);
      if (!cartItem) return;

      const resolution = await pricingApi.resolvePrice({
        productId,
        variantId,
        quantity: cartItem.quantity,
        customerId: customer?.id,
        priceListId: defaultPriceListId,
      });

      if (resolution.price > 0) {
        setCart((current) => current.map((i) => {
          if (i.productId === productId && i.variantId === variantId && i.unitPrice === unitPrice) {
            return {
              ...i,
              unitPrice: resolution.price,
              total: i.quantity * resolution.price - i.discount,
              manualOverride: false,
              priceSource: resolution.source,
              priceSourceName: resolution.appliedRuleName,
            };
          }
          return i;
        }));
      }
    } catch {
      showToast('Failed to reset price', 'error');
    }
  };

  // Re-evaluate all cart prices when customer changes
  const recalculateAllCartPrices = async (customerId?: string) => {
    const hasPricing = pricingRules.length > 0 || priceLists.length > 0;
    if (!hasPricing || cart.length === 0) return;

    // Create a snapshot of items to update with their promises
    const itemsToUpdate = cart
      .filter(item => !item.manualOverride)
      .map(item => ({
        cartItemId: item.cartItemId,
        item,
        promise: pricingApi.resolvePrice({
          productId: item.productId,
          variantId: item.variantId,
          quantity: item.quantity,
          customerId: customerId,
          priceListId: defaultPriceListId,
        }),
      }));

    if (itemsToUpdate.length === 0) return;

    // Wait for all resolutions
    const results = await Promise.allSettled(itemsToUpdate.map(x => x.promise));

    // Update cart using functional state to preserve concurrent changes
    setCart(currentCart => {
      const priceUpdates = new Map<string, { price: number; source: string; sourceName?: string }>();

      itemsToUpdate.forEach((entry, idx) => {
        const result = results[idx];
        if (result.status === 'fulfilled' && result.value.price > 0) {
          priceUpdates.set(entry.cartItemId, {
            price: result.value.price,
            source: result.value.source,
            sourceName: result.value.appliedRuleName,
          });
        }
      });

      // Only update items that have price changes
      return currentCart.map(item => {
        const update = priceUpdates.get(item.cartItemId);
        if (update && update.price !== item.unitPrice) {
          return {
            ...item,
            unitPrice: update.price,
            total: item.quantity * update.price - item.discount,
            priceSource: update.source,
            priceSourceName: update.sourceName,
          };
        }
        return item;
      });
    });
  };

  // Detect available bundles for current cart
  const detectBundles = useCallback(async () => {
    if (cart.length === 0 || appliedBundle) {
      setApplicableBundles([]);
      return;
    }

    setIsDetectingBundles(true);
    try {
      const cartItems = cart.map(item => ({
        productId: item.productId,
        variantId: item.variantId,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
      }));

      const result = await detectBundlesMutation.mutateAsync(cartItems);
      setApplicableBundles(result);
    } catch (error) {
      console.error('Bundle detection failed:', error);
      setApplicableBundles([]);
    } finally {
      setIsDetectingBundles(false);
    }
  }, [cart, appliedBundle, detectBundlesMutation]);

  // Apply bundle to cart
  const handleApplyBundle = async (bundle: ApplicableBundle) => {
    if (!confirm(`Apply "${bundle.bundle.name}" bundle? You'll save ₹${bundle.savings.toFixed(0)}.`)) {
      return;
    }

    try {
      const cartItems = cart.map(item => ({
        cartItemId: item.cartItemId,
        productId: item.productId,
        variantId: item.variantId,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
      }));

      const result = await applyBundleMutation.mutateAsync({
        bundleId: bundle.bundle.id,
        cartItems,
        times: bundle.timesApplicable,
      });

      // Mark items as bundle applied
      setCart(current => current.map(item => {
        const isInBundle = result.appliedItems.some(ai => ai.cartItemId === item.cartItemId);
        if (isInBundle) {
          const appliedItem = result.appliedItems.find(ai => ai.cartItemId === item.cartItemId);
          return {
            ...item,
            priceSource: 'bundle',
            priceSourceName: bundle.bundle.name,
          };
        }
        return item;
      }));

      setAppliedBundle({
        id: bundle.bundle.id,
        name: bundle.bundle.name,
        savings: result.savings,
        appliedItems: result.appliedItems.map(ai => ai.cartItemId),
      });

      setApplicableBundles([]);
      showToast(`Bundle "${bundle.bundle.name}" applied! You saved ₹${result.savings.toFixed(0)}`, 'success');
    } catch (error: any) {
      showToast(error?.response?.data?.message || 'Failed to apply bundle', 'error');
    }
  };

  // Remove applied bundle
  const handleRemoveBundle = () => {
    setCart(current => current.map(item => {
      if (appliedBundle?.appliedItems.includes(item.cartItemId)) {
        return {
          ...item,
          priceSource: 'default',
          priceSourceName: undefined,
        };
      }
      return item;
    }));
    setAppliedBundle(null);
    detectBundles();
  };

  // Detect bundles when cart changes (debounced)
  useEffect(() => {
    const timer = setTimeout(() => {
      detectBundles();
    }, 500);
    return () => clearTimeout(timer);
  }, [cart, detectBundles]);

  const totals = useMemo(() => {
    const grossTotal = cart.reduce(
      (acc, item) => acc + item.quantity * item.unitPrice,
      0,
    );
    const lineDiscount = cart.reduce(
      (acc, item) => acc + (item.discount || 0),
      0,
    );

    // Enterprise discount calculation
    let discountAmount = overallDiscount;
    if (discountType === 'percent') {
      discountAmount = grossTotal * (overallDiscount / 100);
    }
    // Apply caps from settings
    if (discountType === 'flat' && discountAmount > posSettings.discountMaxFlat) {
      discountAmount = posSettings.discountMaxFlat;
    }
    if (discountType === 'percent' && overallDiscount > posSettings.discountMaxPct) {
      discountAmount = grossTotal * (posSettings.discountMaxPct / 100);
    }

    const totalDiscount = lineDiscount + discountAmount;
    const subTotal = grossTotal - totalDiscount;

    // Calculate tax based on interstate setting
    let totalCGST = 0;
    let totalSGST = 0;
    let totalIGST = 0;

    cart.forEach(item => {
      if (item.gstRate && posSettings.gstAutoApply) {
        const itemTotal = item.quantity * item.unitPrice - (item.discount || 0);
        const taxResult = calculateTax(itemTotal, item.gstRate, isInterstate);
        totalCGST += taxResult.cgst;
        totalSGST += taxResult.sgst;
        totalIGST += taxResult.igst;
      }
    });

    const totalTax = totalCGST + totalSGST + totalIGST;
    const grandTotal = Math.round(subTotal + totalTax);
    const roundOff = grandTotal - (subTotal + totalTax);

    // Apply loyalty discount
    const finalGrandTotal = Math.max(0, grandTotal - loyaltyDiscount);
    const roundOffWithLoyalty = finalGrandTotal - (subTotal + totalTax - loyaltyDiscount);

    const balanceDue = Math.max(0, finalGrandTotal - amountReceived);

    // Amount in words
    const amountInWords = numberToWords(finalGrandTotal);

    return {
      grossTotal,
      lineDiscount,
      overallDiscount,
      discountAmount,
      totalDiscount,
      subTotal,
      totalCGST,
      totalSGST,
      totalIGST,
      totalTax,
      grandTotal,
      loyaltyDiscount,
      finalGrandTotal,
      roundOff,
      roundOffWithLoyalty,
      balanceDue,
      amountInWords,
    };
  }, [cart, amountReceived, overallDiscount, discountType, loyaltyDiscount, isInterstate, posSettings.gstAutoApply, posSettings.discountMaxFlat, posSettings.discountMaxPct]);

  const handleCreateBill = () => {
    if (createInvoiceMutation.isPending) return;
    if (overallDiscount < 0) {
      showAlert({ title: 'Invalid Discount', message: 'Overall discount cannot be negative', type: 'error' });
      return;
    }
    const isWalkIn = customer.name === 'Walk-in Customer' && !customer.mobile;
    if ((!customer.name || cart.length === 0) && !isWalkIn) {
      showAlert({ title: 'Missing Information', message: 'Please enter customer details and add items to cart.', type: 'info' });
      return;
    }

    const finalCustomerName = isWalkIn ? 'Walk-in Customer' : customer.name;

    if (!createInvoiceIdempotencyKeyRef.current) {
      createInvoiceIdempotencyKeyRef.current = `inv-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
    }

    const newInvoice: Invoice = {
      id: Date.now().toString(),
      idempotencyKey: createInvoiceIdempotencyKeyRef.current,
      // Let backend generate final invoice number to avoid duplicates.
      // UI still shows best-effort `nextInvoiceNumber` in the header.
      invoiceNumber: '',
      date: new Date().toISOString().split('T')[0],
      time: new Date().toTimeString().split(' ')[0],
      customerName: finalCustomerName,
      customerMobile: customer.mobile,
      customerId: customer.id,
      invoiceTemplateId: selectedTemplateId,
      items: cart,
      subTotal: totals.subTotal,
      totalDiscount: totals.totalDiscount + totals.loyaltyDiscount,
      cgst: totals.totalCGST,
      sgst: totals.totalSGST,
      igst: totals.totalIGST,
      totalTax: totals.totalTax,
      grandTotal: totals.finalGrandTotal,
      roundOff: totals.roundOffWithLoyalty,
      amountReceived,
      balanceDue: totals.balanceDue,
      creditApplied: 0,
      pointsRedeemed: pointsToRedeem,
      paymentStatus:
        totals.balanceDue === 0
          ? PaymentStatus.PAID
          : totals.balanceDue < totals.finalGrandTotal
            ? PaymentStatus.PARTIALLY_PAID
            : PaymentStatus.PENDING,
      paymentMode,
      notes: remarks || STORE_DETAILS.notes,
      // Enterprise fields
      customerType: isWalkIn ? 'walkin' : customerType,
      customerGstin: customer.gstin || '',
      customerAddress: customer.address || '',
      customerState: customer.state || '',
      customerStateCode: customer.stateCode || posSettings.stateCode,
      isInterstate,
      discountType,
      amountInWords: totals.amountInWords,
      // Ship-To
      shipToName: posSettings.enableShipTo ? shipTo.name : '',
      shipToGstin: posSettings.enableShipTo ? shipTo.gstin : '',
      shipToAddress: posSettings.enableShipTo ? shipTo.address : '',
      shipToCity: posSettings.enableShipTo ? shipTo.city : '',
      shipToState: posSettings.enableShipTo ? shipTo.state : '',
      shipToStateCode: posSettings.enableShipTo ? shipTo.stateCode : '',
      // Dispatch
      vehicleNumber: dispatch.vehicle,
      lrNumber: dispatch.lr,
      ewayBillNumber: dispatch.ewayBill,
    };

    createInvoiceMutation.mutate(newInvoice, {
      onSuccess: async (createdInvoice) => {
        createInvoiceIdempotencyKeyRef.current = null;
        // Redeem loyalty points if used
        if (pointsToRedeem > 0 && customer.mobile) {
          try {
            await redeemPointsMutation.mutateAsync({
              mobile: customer.mobile,
              points: pointsToRedeem,
            });
          } catch (error) {
            console.error('Failed to redeem points:', error);
          }
        }

        setCart([]);
        setCustomer({ name: '', mobile: '' });
        setCustomerType('walkin');
        setAmountReceived(0);
        setPointsToRedeem(0);
        setLoyaltyDiscount(0);
        // Reset enterprise fields
        setShipTo({ name: '', gstin: '', address: '', city: '', state: '', stateCode: '33' });
        setDispatch({ vehicle: '', lr: '', ewayBill: '' });
        setOverallDiscount(0);
        setRemarks('');
        // Fetch next invoice number for the next bill
        try {
          const result = await invoiceApi.getNextInvoiceNumber();
          setNextInvoiceNumber(result.invoice_number);
        } catch {
          const prefix = posSettings.billPrefix || 'INV';
          setNextInvoiceNumber(`${prefix}/${String(billCounter + 1).padStart(4, '0')}`);
        }

        queryClient.invalidateQueries({
          queryKey: queryKeys.products.lists(),
        });

        // Store the created invoice and auto-open PDF preview modal
        setCreatedInvoiceForPreview(createdInvoice);
        setShowPdfPreview(true);
      },

      onError: (error: any) => {
        console.error('Failed to create invoice:', error);
        const errorMessage = error?.response?.data?.message || 'Failed to create invoice. Please try again.';
        showAlert({
          title: 'Error',
          message: errorMessage,
          type: 'error'
        });
      },
    });
  };

  if (productsLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-sm text-slate-500">Loading products...</div>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-3">
      {/* Left column - Customer & POS */}
      <div className="lg:col-span-2 space-y-3">
        {/* Invoice Number Bar */}
        <div className="bg-gradient-to-r from-indigo-500 to-purple-600 rounded-lg p-2.5 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-1.5 bg-white/20 rounded-md">
              <Receipt size={16} className="text-white" />
            </div>
            <div>
              <p className="text-[10px] text-white/70 font-medium">Next Invoice</p>
              <p className="text-lg font-bold text-white font-mono tracking-wider leading-tight">
                {nextInvoiceNumber || '...'}
              </p>
            </div>
          </div>
          <div className="text-right">
            <p className="text-[10px] text-white/70">{new Date().toLocaleDateString('en-IN', { day:'2-digit', month:'short', year:'numeric' })}</p>
            <p className="text-xs text-white/90 font-mono">{new Date().toLocaleTimeString('en-IN', { hour:'2-digit', minute:'2-digit' })}</p>
          </div>
        </div>

        {/* Customer details */}
        <div className="bg-white rounded-lg border border-slate-200 shadow-sm p-3">
          <div className="flex items-center justify-between mb-2">
            <h3 className="text-sm font-semibold text-slate-900 flex items-center gap-1.5">
              <User size={14} className="text-indigo-600" />
              Customer
            </h3>
            <div className="flex items-center gap-2">
              {/* Customer Type Badge */}
              {customerType !== 'walkin' && (
                <span className={`px-2 py-1 rounded-md text-xs font-semibold ${
                  customerType === 'wholesale' ? 'bg-emerald-100 text-emerald-700' :
                  customerType === 'credit' ? 'bg-amber-100 text-amber-700' :
                  'bg-blue-100 text-blue-700'
                }`}>
                  {customerType.charAt(0).toUpperCase() + customerType.slice(1)}
                </span>
              )}
              <button
                type="button"
                onClick={() => {
                  setCustomer({ name: 'Walk-in Customer', mobile: '', id: undefined, customerTierId: undefined, customerTier: undefined, totalSpent: undefined, loyaltyPoints: undefined, loyaltyAvailablePoints: undefined, loyaltyRedemptionValue: undefined });
                  setCustomerType('walkin');
                  setPointsToRedeem(0);
                  setLoyaltyDiscount(0);
                  // Re-evaluate prices without customer (default pricing)
                  recalculateAllCartPrices(undefined);
                }}
                className={`text-[10px] flex items-center gap-1 font-medium px-2 py-1 rounded transition-colors ${
                  customer.name === 'Walk-in Customer' && !customer.mobile
                    ? 'bg-indigo-100 text-indigo-700 border border-indigo-200'
                    : 'bg-slate-50 text-slate-600 border border-slate-200 hover:bg-indigo-50 hover:text-indigo-600'
                }`}
                title="Quick checkout without customer details"
              >
                <UserPlus size={12} />
                Walk-in
              </button>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <div className="relative">
              <User
                className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400"
                size={14}
              />
              <input
                placeholder="Customer name"
                className="w-full pl-8 pr-2 py-2 bg-slate-50 border border-slate-200 rounded-md text-sm focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500"
                value={customer.name}
                onChange={(e) =>
                  setCustomer({ ...customer, name: e.target.value })
                }
              />
              {/* Show multiple name suggestions if available */}
              {customerOptions.find(opt => opt.mobile === customer.mobile)?.all_names?.length > 1 && (
                <div className="mt-2 flex flex-wrap gap-1 border-t border-slate-100 pt-2">
                  <span className="text-[10px] text-slate-400 w-full mb-0.5">Known names for {customer.mobile}:</span>
                  {customerOptions.find(opt => opt.mobile === customer.mobile)?.all_names.map((n: string) => (
                    <button
                      key={n}
                      type="button"
                      onClick={() => setCustomer({ ...customer, name: n })}
                      className={`text-[11px] px-2 py-1 rounded-full border transition-colors ${customer.name === n ? 'bg-indigo-50 border-indigo-200 text-indigo-700 font-medium' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
                    >
                      {n}
                    </button>
                  ))}
                </div>
              )}
            </div>
            <div className="relative" ref={dropdownRef}>
              <Phone
                className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400"
                size={14}
              />
              <input
                placeholder="Search mobile or name..."
                className="w-full pl-8 pr-8 py-2 bg-slate-50 border border-slate-200 rounded-md text-sm focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500"
                value={customer.mobile}
                onChange={(e) =>
                  setCustomer({ ...customer, mobile: e.target.value })
                }
                onFocus={() => {
                  if (customerOptions.length > 0) setShowCustomerDropdown(true);
                }}
              />
              {isSearchingCustomer && (
                <div className="absolute right-3 top-1/2 -translate-y-1/2">
                  <div className="w-4 h-4 rounded-full border-2 border-slate-300 border-t-indigo-600 animate-spin"></div>
                </div>
              )}

              {showCustomerDropdown && customerOptions.length > 0 && (
                <div className="absolute top-full left-0 w-full mt-1 bg-white border border-slate-200 rounded-xl shadow-lg z-20 max-h-64 overflow-y-auto">
                  {customerOptions.map((opt) => (
                    <button
                      key={opt.mobile}
                      type="button"
                      onClick={() => {
                        const newCustomer = {
                          name: opt.latest_name,
                          mobile: opt.mobile,
                          id: opt.id,
                          customerTierId: opt.customer_tier_id,
                          customerTier: opt.customer_tier,
                          totalSpent: opt.total_spent,
                          loyaltyPoints: undefined,
                          loyaltyAvailablePoints: undefined,
                          loyaltyRedemptionValue: undefined,
                          customerType: opt.customer_type || 'retail',
                          state: opt.state,
                          stateCode: opt.state_code,
                          gstin: opt.gstin,
                          address: opt.address,
                        };
                        setCustomer(newCustomer);
                        // Set customer type for enterprise pricing
                        const cType = (opt.customer_type || 'retail') as 'retail' | 'wholesale' | 'credit' | 'walkin';
                        setCustomerType(cType);
                        setShowCustomerDropdown(false);
                        setPointsToRedeem(0);
                        setLoyaltyDiscount(0);
                        // Re-evaluate prices for the new customer
                        recalculateAllCartPrices(opt.id);
                        // Fetch loyalty points
                        loyaltyApi.getCustomerPoints(opt.mobile).then(loyaltyData => {
                          if (loyaltyData.available_points > 0 && loyaltySettings?.is_enabled) {
                            const redeemValue = loyaltyData.available_points * (loyaltyData.redeem_value_per_point || 1);
                            setCustomer(prev => ({
                              ...prev,
                              loyaltyPoints: loyaltyData.total_points,
                              loyaltyAvailablePoints: loyaltyData.available_points,
                              loyaltyRedemptionValue: redeemValue,
                            }));
                          }
                        }).catch(error => {
                          console.error('Failed to fetch loyalty points:', error);
                        });
                      }}
                      className="w-full text-left p-3 hover:bg-slate-50 transition-colors border-b border-slate-50 last:border-0 flex justify-between items-center"
                    >
                      <div>
                        <div className="flex items-center gap-2">
                          <p className="font-medium text-slate-900 text-sm">{opt.mobile}</p>
                          {opt.customer_tier && (
                            <span
                              className="px-1.5 py-0.5 rounded text-[10px] font-semibold"
                              style={{
                                backgroundColor: opt.customer_tier.color + '20',
                                color: opt.customer_tier.color
                              }}
                            >
                              {opt.customer_tier.name}
                            </span>
                          )}
                        </div>
                        <p className="text-xs text-slate-500 flex gap-1">
                          {opt.all_names.length > 1 ? (
                            <span className="text-indigo-600 font-medium" title={opt.all_names.join(', ')}>
                              {opt.all_names.length} names
                            </span>
                          ) : (
                            <span>{opt.latest_name}</span>
                          )}
                        </p>
                      </div>
                      <div className="text-right">
                        <p className="text-xs font-semibold text-emerald-600">₹{(opt.total_spent || 0).toLocaleString('en-IN')}</p>
                        <p className="text-[10px] text-slate-400">{opt.total_visits} visits</p>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Loyalty Points Section */}
          {customer.mobile && loyaltySettings?.is_enabled && (
            <div className="mt-4 pt-4 border-t border-slate-100">
              <div className="bg-gradient-to-r from-indigo-50 to-purple-50 rounded-lg p-4">
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <Gift className="w-5 h-5 text-indigo-600" />
                    <span className="font-semibold text-indigo-900">Loyalty Points</span>
                  </div>
                  {customer.loyaltyAvailablePoints !== undefined && customer.loyaltyAvailablePoints > 0 && (
                    <div className="text-right">
                      <p className="text-2xl font-bold text-indigo-600">
                        {customer.loyaltyAvailablePoints.toLocaleString()}
                      </p>
                      <p className="text-xs text-indigo-600">points available</p>
                    </div>
                  )}
                </div>

                {customer.loyaltyAvailablePoints !== undefined && customer.loyaltyAvailablePoints > 0 ? (
                  <div className="space-y-3">
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-indigo-700">Redeem value:</span>
                      <span className="font-semibold text-indigo-900">
                        ₹{((customer.loyaltyAvailablePoints || 0) * (loyaltySettings?.redeem_value_per_point || 1)).toLocaleString()}
                      </span>
                    </div>

                    <div className="flex items-center gap-2">
                      <input
                        type="range"
                        min="0"
                        max={customer.loyaltyAvailablePoints}
                        step={Math.max(1, Math.floor((customer.loyaltyAvailablePoints || 100) / 10))}
                        value={pointsToRedeem}
                        onChange={(e) => {
                          const pts = parseInt(e.target.value);
                          setPointsToRedeem(pts);
                          setLoyaltyDiscount(pts * (loyaltySettings?.redeem_value_per_point || 1));
                        }}
                        className="flex-1 h-2 bg-indigo-200 rounded-lg appearance-none cursor-pointer"
                      />
                      <input
                        type="number"
                        min="0"
                        max={customer.loyaltyAvailablePoints}
                        value={pointsToRedeem}
                        onChange={(e) => {
                          const pts = Math.min(parseInt(e.target.value) || 0, customer.loyaltyAvailablePoints || 0);
                          setPointsToRedeem(pts);
                          setLoyaltyDiscount(pts * (loyaltySettings?.redeem_value_per_point || 1));
                        }}
                        className="w-24 px-2 py-1 border border-indigo-200 rounded-lg text-sm text-center"
                      />
                    </div>

                    {pointsToRedeem > 0 && (
                      <div className="flex items-center justify-between bg-white/60 rounded-lg px-3 py-2">
                        <span className="text-sm text-indigo-700">Points discount:</span>
                        <span className="font-bold text-emerald-600">
                          -₹{loyaltyDiscount.toLocaleString()}
                        </span>
                      </div>
                    )}

                    {loyaltySettings?.minimum_points_to_redeem && pointsToRedeem < (loyaltySettings?.minimum_points_to_redeem || 0) && pointsToRedeem > 0 && (
                      <p className="text-xs text-amber-600">
                        Min {loyaltySettings?.minimum_points_to_redeem} points required to redeem
                      </p>
                    )}
                  </div>
                ) : (
                  <p className="text-sm text-indigo-600">
                    {customer.loyaltyAvailablePoints === 0 ? 'No points available' : 'Loading points...'}
                  </p>
                )}
              </div>
            </div>
          )}

          {/* Enterprise: Ship-To / Consignee Section */}
          {posSettings.enableShipTo && (
            <div className="mt-3 pt-3 border-t border-slate-100">
              <div className="flex items-center gap-1.5 mb-2">
                <MapPin size={12} className="text-slate-500" />
                <span className="text-xs font-semibold text-slate-700">Ship-To / Consignee</span>
              </div>
              <div className="grid grid-cols-2 gap-2 p-2 bg-slate-50 rounded-md border border-slate-200">
                <input
                  type="text"
                  placeholder="Consignee Name"
                  value={shipTo.name}
                  onChange={(e) => setShipTo({ ...shipTo, name: e.target.value })}
                  className="px-2 py-1.5 border border-slate-200 rounded text-xs"
                />
                <input
                  type="text"
                  placeholder="Consignee GSTIN"
                  value={shipTo.gstin}
                  onChange={(e) => setShipTo({ ...shipTo, gstin: e.target.value })}
                  className="px-2 py-1.5 border border-slate-200 rounded text-xs font-mono"
                />
                <input
                  type="text"
                  placeholder="Shipping Address"
                  value={shipTo.address}
                  onChange={(e) => setShipTo({ ...shipTo, address: e.target.value })}
                  className="col-span-2 px-2 py-1.5 border border-slate-200 rounded text-xs"
                />
                <input
                  type="text"
                  placeholder="City"
                  value={shipTo.city}
                  onChange={(e) => setShipTo({ ...shipTo, city: e.target.value })}
                  className="px-2 py-1.5 border border-slate-200 rounded text-xs"
                />
                <select
                  value={shipTo.stateCode}
                  onChange={(e) => setShipTo({ ...shipTo, stateCode: e.target.value, state: e.target.selectedOptions[0].dataset.name || '' })}
                  className="px-2 py-1.5 border border-slate-200 rounded text-xs"
                >
                  <option value="33" data-name="Tamil Nadu">Tamil Nadu (33)</option>
                  <option value="27" data-name="Maharashtra">Maharashtra (27)</option>
                  <option value="09" data-name="Uttar Pradesh">Uttar Pradesh (09)</option>
                  <option value="24" data-name="Gujarat">Gujarat (24)</option>
                  <option value="29" data-name="Karnataka">Karnataka (29)</option>
                  <option value="07" data-name="Delhi">Delhi (07)</option>
                  <option value="32" data-name="Kerala">Kerala (32)</option>
                  <option value="23" data-name="Madhya Pradesh">Madhya Pradesh (23)</option>
                  <option value="08" data-name="Rajasthan">Rajasthan (08)</option>
                </select>
              </div>
            </div>
          )}
        </div>

        {/* Enterprise: Dispatch Details */}
        {posSettings.enableDispatch && (
          <div className="bg-white rounded-lg border border-slate-200 shadow-sm p-3">
            <div className="flex items-center gap-1.5 mb-2">
              <Truck size={14} className="text-slate-600" />
              <h3 className="text-xs font-semibold text-slate-900">Dispatch</h3>
            </div>
            <div className="grid grid-cols-3 gap-2">
              <div>
                <input
                  type="text"
                  placeholder="Vehicle No."
                  value={dispatch.vehicle}
                  onChange={(e) => setDispatch({ ...dispatch, vehicle: e.target.value })}
                  className="w-full px-2 py-1.5 border border-slate-200 rounded text-xs font-mono"
                />
              </div>
              <div>
                <input
                  type="text"
                  placeholder="LR / Docket"
                  value={dispatch.lr}
                  onChange={(e) => setDispatch({ ...dispatch, lr: e.target.value })}
                  className="w-full px-2 py-1.5 border border-slate-200 rounded text-xs font-mono"
                />
              </div>
              <div>
                <input
                  type="text"
                  placeholder="E-Way Bill No."
                  value={dispatch.ewayBill}
                  onChange={(e) => setDispatch({ ...dispatch, ewayBill: e.target.value })}
                  className="w-full px-2 py-1.5 border border-slate-200 rounded text-xs font-mono"
                />
              </div>
            </div>
          </div>
        )}

        {/* POS Search */}
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
          {/* Manual Mode Inline Form */}
          {manualMode ? (
            <div className="mb-4">
              <div className="flex items-center justify-between mb-3 p-3 bg-gradient-to-r from-amber-50 to-orange-50 border border-amber-200 rounded-lg">
                <div className="flex items-center gap-2">
                  <span className="text-amber-600">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                    </svg>
                  </span>
                  <span className="text-sm font-medium text-amber-800">Manual Item Entry</span>
                  <span className="text-xs text-amber-600">— Add custom items not in your database</span>
                </div>
                <label className="relative inline-flex items-center cursor-pointer">
                  <input
                    type="checkbox"
                    checked={false}
                    onChange={() => setManualMode(false)}
                    className="sr-only peer"
                  />
                  <div className="w-9 h-5 bg-amber-200 peer-focus:ring-2 peer-focus:ring-indigo-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-indigo-600"></div>
                  <span className="ml-2 text-xs font-medium text-slate-600">Search</span>
                </label>
              </div>
              <form
                onSubmit={(e) => {
                  e.preventDefault();
                  if (manualItemForm.name.trim() && manualItemForm.price > 0 && manualItemForm.quantity > 0) {
                    addManualItem(
                      manualItemForm.name,
                      manualItemForm.price,
                      manualItemForm.quantity,
                      manualItemForm.gstRate,
                      undefined,
                      undefined,
                      undefined
                    );
                    setManualItemForm({ name: '', price: 0, quantity: 1, gstRate: 0, primaryUnitId: '', secondaryUnitId: '', conversionFactor: 1 });
                  }
                }}
                className="grid grid-cols-12 gap-3"
              >
                <div className="col-span-5">
                  <input
                    type="text"
                    placeholder="Item name *"
                    value={manualItemForm.name}
                    onChange={(e) => setManualItemForm({ ...manualItemForm, name: e.target.value })}
                    className="w-full px-3 py-2.5 border border-slate-200 rounded-lg text-sm focus:border-amber-500 focus:ring-1 focus:ring-amber-500"
                    autoFocus
                  />
                </div>
                <div className="col-span-2">
                  <input
                    type="number"
                    placeholder="Price ₹ *"
                    min="0.01"
                    step="0.01"
                    value={manualItemForm.price || ''}
                    onChange={(e) => setManualItemForm({ ...manualItemForm, price: parseFloat(e.target.value) || 0 })}
                    className="w-full px-3 py-2.5 border border-slate-200 rounded-lg text-sm focus:border-amber-500 focus:ring-1 focus:ring-amber-500"
                  />
                </div>
                <div className="col-span-1">
                  <input
                    type="number"
                    placeholder="Qty"
                    min="1"
                    value={manualItemForm.quantity}
                    onChange={(e) => setManualItemForm({ ...manualItemForm, quantity: parseInt(e.target.value) || 1 })}
                    className="w-full px-3 py-2.5 border border-slate-200 rounded-lg text-sm focus:border-amber-500 focus:ring-1 focus:ring-amber-500"
                  />
                </div>
                <div className="col-span-2">
                  <select
                    value={manualItemForm.gstRate}
                    onChange={(e) => setManualItemForm({ ...manualItemForm, gstRate: parseFloat(e.target.value) })}
