                onClick={() => { setShowSerialModal(false); setSerialNumbers([]); setSerialInput(''); }}
                className="text-slate-500 hover:text-slate-700 hover:bg-slate-200 rounded-full p-1"
              >
                <X size={20} />
              </button>
            </div>
            <div className="p-5">
              <p className="text-sm text-slate-600 mb-3">
                Product: <span className="font-medium">{serialProduct?.displayName}</span>
              </p>
              <p className="text-xs text-slate-500 mb-4">
                Enter serial numbers for each unit (one per line or press Enter after each)
              </p>

              <div className="flex gap-2 mb-3">
                <input
                  type="text"
                  value={serialInput}
                  onChange={(e) => setSerialInput(e.target.value.toUpperCase())}
                  onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addSerialNumber(); } }}
                  placeholder="Scan or type serial number..."
                  className="flex-1 px-3 py-2 border border-slate-300 rounded-lg text-sm font-mono"
                  autoFocus
                />
                <button
                  type="button"
                  onClick={addSerialNumber}
                  className="px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm font-medium hover:bg-indigo-700"
                >
                  Add
                </button>
              </div>

              <div className="border border-slate-200 rounded-lg max-h-48 overflow-y-auto">
                {serialNumbers.length === 0 ? (
                  <p className="p-4 text-center text-sm text-slate-400">No serial numbers added yet</p>
                ) : (
                  <div className="p-2 space-y-1">
                    {serialNumbers.map((serial, idx) => (
                      <div key={idx} className="flex items-center justify-between px-3 py-2 bg-slate-50 rounded text-sm font-mono">
                        <span>{serial}</span>
                        <button
                          type="button"
                          onClick={() => removeSerialNumber(idx)}
                          className="text-slate-400 hover:text-rose-500"
                        >
                          <X size={14} />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
