/** Convert any SKU to a valid 11-digit UPC number (check digit auto-calculated by scanner) */
function toUPC(value: string): string {
  let digits = value.replace(/[^0-9]/g, '');
  if (!digits) {
    let hash = 0;
    for (let i = 0; i < value.length; i++) {
      hash = ((hash << 5) - hash + value.charCodeAt(i)) >>> 0;
    }
    digits = String(hash);
  }
  if (digits.length >= 12) {
    digits = digits.substring(0, 11);
  } else {
    digits = digits.padStart(11, '0');
  }
  return digits;
}

/** Calculate UPC-A check digit for an 11-digit string */
function upcCheckDigit(code: string): string {
  let odd = 0, even = 0;
  for (let i = 0; i < 11; i++) {
    if (i % 2 === 0) odd += parseInt(code[i]);
    else even += parseInt(code[i]);
  }
  const check = (10 - ((odd * 3 + even) % 10)) % 10;
  return code + check;
}

/** Get full 12-digit UPC-A from any SKU */
function skuToFullUPC(sku: string): string {
  return upcCheckDigit(toUPC(sku));
}

