                  const tempInvoice = {
                    id: `temp-${Date.now()}`,
                    invoiceNumber: `INV-${Date.now()}`,
                    date: new Date().toISOString().split('T')[0],
                    time: new Date().toTimeString().split(' ')[0],
                    customerName: customer.name || 'Walk-in Customer',
                    customerMobile: customer.mobile,
                    customerId: customer.id,
                    invoiceTemplateId: selectedTemplateId,
                    items: cart,
                    subTotal: totals.subTotal,
                    totalDiscount: totals.totalDiscount + totals.loyaltyDiscount,
                    cgst: totals.totalCGST,
                    sgst: totals.totalSGST,
                    igst: totals.totalIGST,
                    totalTax: totals.totalTax,
                    grandTotal: totals.finalGrandTotal,
                    roundOff: totals.roundOffWithLoyalty,
                    amountReceived: paymentMode === 'cash' ? totals.finalGrandTotal : 0,
                    balanceDue: totals.balanceDue,
                    creditApplied: 0,
                    pointsRedeemed: 0,
                    paymentStatus: totals.balanceDue === 0 ? PaymentStatus.PAID : PaymentStatus.PENDING,
                    paymentMode,
                    notes: remarks || STORE_DETAILS.notes,
                    customerType: customer.type || 'walkin',
                    customerGstin: customer.gstin || '',
                    customerAddress: customer.address || '',
                    customerState: customer.state || '',
                    customerStateCode: customer.stateCode || posSettings.stateCode,
                    isInterstate: false,
                    discountType: 'flat',
                    amountInWords: totals.amountInWords,
                    shipToName: '',
                    shipToGstin: '',
                    shipToAddress: '',
                    shipToCity: '',
                    shipToState: '',
                    shipToStateCode: '',
                    vehicleNumber: '',
                    lrNumber: '',
