              >
                <Printer size={14} />
                Print PDF
              </button>
              <button
                type="button"
                onClick={() => {
                  // Create a temporary invoice object for receipt download
                  const tempInvoice = {
                    id: `temp-${Date.now()}`,
                    invoiceNumber: `INV-${Date.now()}`,
                    date: new Date().toISOString().split('T')[0],
                    time: new Date().toTimeString().split(' ')[0],
                    customerName: customer.name || 'Walk-in Customer',
                    customerMobile: customer.mobile,
                    customerId: customer.id,
                    invoiceTemplateId: selectedTemplateId,
                    items: cart,
                    subTotal: totals.subTotal,
                    totalDiscount: totals.totalDiscount + totals.loyaltyDiscount,
                    cgst: totals.totalCGST,
                    sgst: totals.totalSGST,
                    igst: totals.totalIGST,
                    totalTax: totals.totalTax,
                    grandTotal: totals.finalGrandTotal,
                    roundOff: totals.roundOffWithLoyalty,
                    amountReceived: paymentMode === 'cash' ? totals.finalGrandTotal : 0,
                    balanceDue: totals.balanceDue,
                    creditApplied: 0,
                    pointsRedeemed: 0,
                    paymentStatus: totals.balanceDue === 0 ? PaymentStatus.PAID : PaymentStatus.PENDING,
                    paymentMode,
                    notes: remarks || STORE_DETAILS.notes,
                    customerType: customer.type || 'walkin',
                    customerGstin: customer.gstin || '',
                    customerAddress: customer.address || '',
                    customerState: customer.state || '',
                    customerStateCode: customer.stateCode || posSettings.stateCode,
                    isInterstate: false,
                    discountType: 'flat',
                    amountInWords: totals.amountInWords,
                    shipToName: '',
                    shipToGstin: '',
                    shipToAddress: '',
                    shipToCity: '',
                    shipToState: '',
                    shipToStateCode: '',
                    vehicleNumber: '',
                    lrNumber: '',
                    ewayBillNumber: '',
                  };
                  // Download payment receipt using the same function as Sales History
                  generatePaymentReceiptPdf(tempInvoice, false);
                }}
                className="flex items-center justify-center gap-2 px-3 py-2 rounded-lg border border-amber-200 bg-amber-50 text-amber-700 text-xs font-medium hover:bg-amber-100"
              >
                <Receipt size={14} />
                Download Receipt
              </button>
              <button
                type="button"
                onClick={() => setShowPdfPreview(true)}
                className="flex items-center justify-center gap-2 px-3 py-2 rounded-lg border border-indigo-200 bg-indigo-50 text-indigo-700 text-xs font-medium hover:bg-indigo-100"
              >
                <FileText size={14} />
                Preview PDF
              </button>
              <button
                type="button"
                onClick={() => {
                  const invoiceNum = `INV-${Date.now()}`;
                  setBillQRData({ value: invoiceNum, title: `Invoice #${invoiceNum}` });
                  setShowBillQR(true);
                }}
                className="flex items-center justify-center gap-2 px-3 py-2 rounded-lg border border-slate-200 bg-white text-slate-700 text-xs font-medium hover:bg-slate-50"
              >
                <QrCode size={14} />
                Show QR
              </button>
              <button
                type="button"
                onClick={() => {
                  const invoiceNum = `INV-${Date.now()}`;
                  setBillBarcodeData({
                    value: invoiceNum,
                    title: `Invoice #${invoiceNum}`
                  });
                  setShowBillBarcode(true);
                }}
                className="flex items-center justify-center gap-2 px-3 py-2 rounded-lg border border-slate-200 bg-white text-slate-700 text-xs font-medium hover:bg-slate-50"
              >
                <Barcode size={16} />
                Show Barcode
              </button>
            </div>
          )}
        </div>
      </div>
      <QRCodeGenerator
        isOpen={showBillQR}
        onClose={() => setShowBillQR(false)}
        value={billQRData.value}
        title={billQRData.title}
      />

      <BarcodeGenerator
        isOpen={showBillBarcode}
        onClose={() => setShowBillBarcode(false)}
        value={billBarcodeData.value}
        title={billBarcodeData.title}
      />

      {/* Serial Number Modal */}
      {showSerialModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-md animate-in fade-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between px-5 py-4 border-b border-slate-200 bg-slate-50 rounded-t-2xl">
              <h3 className="text-lg font-semibold text-slate-900">Enter Serial Numbers</h3>
              <button
                onClick={() => { setShowSerialModal(false); setSerialNumbers([]); setSerialInput(''); }}
                className="text-slate-500 hover:text-slate-700 hover:bg-slate-200 rounded-full p-1"
              >
                <X size={20} />
              </button>
            </div>
            <div className="p-5">
              <p className="text-sm text-slate-600 mb-3">
                Product: <span className="font-medium">{serialProduct?.displayName}</span>
              </p>
              <p className="text-xs text-slate-500 mb-4">
                Enter serial numbers for each unit (one per line or press Enter after each)
              </p>

              <div className="flex gap-2 mb-3">
                <input
                  type="text"
                  value={serialInput}
                  onChange={(e) => setSerialInput(e.target.value.toUpperCase())}
                  onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addSerialNumber(); } }}
                  placeholder="Scan or type serial number..."
                  className="flex-1 px-3 py-2 border border-slate-300 rounded-lg text-sm font-mono"
                  autoFocus
                />
                <button
                  type="button"
                  onClick={addSerialNumber}
                  className="px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm font-medium hover:bg-indigo-700"
                >
                  Add
                </button>
              </div>

              <div className="border border-slate-200 rounded-lg max-h-48 overflow-y-auto">
                {serialNumbers.length === 0 ? (
                  <p className="p-4 text-center text-sm text-slate-400">No serial numbers added yet</p>
                ) : (
                  <div className="p-2 space-y-1">
                    {serialNumbers.map((serial, idx) => (
                      <div key={idx} className="flex items-center justify-between px-3 py-2 bg-slate-50 rounded text-sm font-mono">
                        <span>{serial}</span>
                        <button
                          type="button"
                          onClick={() => removeSerialNumber(idx)}
                          className="text-slate-400 hover:text-rose-500"
                        >
                          <X size={14} />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
              <p className="text-xs text-slate-500 mt-2">Added: {serialNumbers.length}</p>
            </div>
            <div className="px-5 py-4 border-t border-slate-200 bg-slate-50 rounded-b-2xl flex justify-end gap-3">
              <button
                onClick={() => { setShowSerialModal(false); setSerialNumbers([]); setSerialInput(''); }}
                className="px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-200 rounded-lg"
              >
                Cancel
              </button>
              <button
                onClick={handleAddToCartWithSerial}
                disabled={serialNumbers.length === 0}
                className="px-4 py-2 text-sm font-medium bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Add to Cart
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Batch Number Modal */}
      {showBatchModal && (
        <BatchModalEnhanced
          product={batchProduct}
          batchInfo={batchInfo}
          setBatchInfo={setBatchInfo}
          onClose={() => {
            setShowBatchModal(false);
            setBatchProduct(null);
          }}
          onAdd={(expiryDate) => {
            if (batchProduct && batchInfo.quantity > 0) {
              addToCart(batchProduct, undefined, batchInfo.batchNumber || 'N/A', expiryDate);
              setShowBatchModal(false);
              setBatchProduct(null);
              showToast(`Added ${batchProduct.displayName} to cart`, 'success');
            }
          }}
        />
      )}

      <QRScannerModal
        isOpen={showScanner}
        onClose={() => setShowScanner(false)}
        onScan={handleScanResult}
      />

      {/* Manual Item Modal */}
      <ManualItemModal
        isOpen={showManualItemModal}
        onClose={() => {
          setShowManualItemModal(false);
          setManualItemForm({ name: '', price: 0, quantity: 1, gstRate: 0, primaryUnitId: '', secondaryUnitId: '', conversionFactor: 1 });
        }}
        onAdd={addManualItem}
        form={manualItemForm}
        setForm={setManualItemForm}
      />

      {/* PDF Preview Modal */}
      <PdfPreviewModal
        isOpen={showPdfPreview}
        onClose={() => {
          setShowPdfPreview(false);
          setCreatedInvoiceForPreview(null);
        }}
        cart={createdInvoiceForPreview?.items || cart}
        customer={{
          name: createdInvoiceForPreview?.customerName || customer.name || 'Walk-in Customer',
          mobile: createdInvoiceForPreview?.customerMobile || customer.mobile || '',
          address: createdInvoiceForPreview?.customerAddress || customer.address || '',
          gstin: createdInvoiceForPreview?.customerGstin || customer.gstin || '',
          email: customer.email || '',
        }}
        pdfSettings={undefined}
        totals={{
          subtotal: createdInvoiceForPreview?.subTotal || totals.subTotal,
          discount: createdInvoiceForPreview?.totalDiscount || totals.totalDiscount,
          tax: createdInvoiceForPreview?.totalTax || totals.totalTax,
          grandTotal: createdInvoiceForPreview?.grandTotal || totals.finalGrandTotal,
          roundOff: createdInvoiceForPreview?.roundOff || totals.roundOffWithLoyalty,
        }}
        remarks={createdInvoiceForPreview?.notes || remarks}
        paymentMode={createdInvoiceForPreview?.paymentMode || paymentMode}
        onDownloadReceipt={() => {
          if (createdInvoiceForPreview) {
            generatePaymentReceiptPdf(createdInvoiceForPreview, false);
          }
        }}
      />

      {/* Enterprise Settings Panel */}
      <EnterpriseSettingsPanel
        isOpen={showSettings}
        onClose={() => setShowSettings(false)}
        settings={posSettings}
        onSettingsChange={setPosSettings}
      />
    </div>
  );
};

// Enhanced Batch Modal Component
interface BatchModalEnhancedProps {
  product: any;
  batchInfo: { batchNumber: string; quantity: number; expiryDate?: string };
  setBatchInfo: React.Dispatch<React.SetStateAction<{ batchNumber: string; quantity: number; expiryDate?: string }>>;
  onClose: () => void;
  onAdd: (expiryDate?: string) => void;
}

const BatchModalEnhanced: React.FC<BatchModalEnhancedProps> = ({ product, batchInfo, setBatchInfo, onClose, onAdd }) => {
  const { data: availableBatches = [], isLoading: batchesLoading } = useAvailableBatches(product?.id);

  const selectedBatch = availableBatches.find((b: any) => b.batch_number === batchInfo.batchNumber);

  const getExpiryBadge = (batch: any) => {
    if (batch.is_expired) {
      return (
        <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800">
          Expired
        </span>
      );
    }
    if (batch.is_expiring_soon) {
      return (
        <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-orange-100 text-orange-800">
          {batch.expiry_warning || 'Expiring Soon'}
        </span>
      );
    }
    if (batch.expiry_date) {
      return (
        <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
          Exp: {batch.expiry_date}
        </span>
      );
    }
    return null;
  };

  const isNewBatch = batchInfo.batchNumber && !availableBatches.find((b: any) => b.batch_number === batchInfo.batchNumber);

  const maxQty = selectedBatch?.available_qty || product?.displayStock || 999;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg animate-in fade-in zoom-in-95 duration-200">
        <div className="flex items-center justify-between px-5 py-4 border-b border-slate-200 bg-slate-50 rounded-t-2xl">
          <h3 className="text-lg font-semibold text-slate-900">Select Batch</h3>
          <button onClick={onClose} className="text-slate-500 hover:text-slate-700 hover:bg-slate-200 rounded-full p-1">
            <X size={20} />
          </button>
        </div>

        <div className="p-5 space-y-4 max-h-[60vh] overflow-y-auto">
          <div className="bg-slate-50 p-3 rounded-lg">
            <p className="font-medium text-slate-900">{product?.displayName}</p>
            <p className="text-sm text-slate-500">Available Stock: {product?.displayStock}</p>
          </div>

          {batchesLoading ? (
            <div className="text-center py-4 text-slate-500">Loading batches...</div>
          ) : availableBatches.length > 0 ? (
            <div className="space-y-2">
              <label className="block text-sm font-medium text-slate-700">Select Existing Batch</label>
              <div className="space-y-2 max-h-48 overflow-y-auto border border-slate-200 rounded-lg p-2">
                {availableBatches.map((batch: any) => (
                  <button
                    key={batch.batch_number}
                    onClick={() => setBatchInfo({
                      ...batchInfo,
                      batchNumber: batch.batch_number,
                      expiryDate: batch.expiry_date,
                    })}
                    className={`w-full p-3 rounded-lg border text-left transition-colors ${
                      batchInfo.batchNumber === batch.batch_number
                        ? 'border-indigo-500 bg-indigo-50'
                        : 'border-slate-200 hover:border-slate-300'
                    } ${batch.is_expired ? 'opacity-60' : ''}`}
                  >
                    <div className="flex justify-between items-start">
                      <div>
                        <p className="font-mono font-medium text-slate-900">{batch.batch_number}</p>
                        <div className="flex items-center gap-2 mt-1">
                          <span className="text-sm text-slate-600">
                            Stock: {batch.available_qty}
                          </span>
                          {getExpiryBadge(batch)}
                        </div>
                      </div>
                      {batchInfo.batchNumber === batch.batch_number && (
                        <CheckCircle size={18} className="text-indigo-600 flex-shrink-0" />
                      )}
                    </div>
                  </button>
                ))}
              </div>
            </div>
          ) : (
            <p className="text-sm text-slate-500 text-center py-2">No batches with available stock for this product.</p>
          )}

          <div className="border-t border-slate-200 pt-4">
            <label className="flex items-center gap-2 text-sm text-slate-600 cursor-pointer">
              <input
                type="checkbox"
                checked={isNewBatch}
                onChange={(e) => {
                  if (e.target.checked) {
                    setBatchInfo({ batchNumber: '', quantity: 1, expiryDate: undefined });
                  }
                }}
                className="rounded border-slate-300 text-indigo-600"
              />
              Enter new batch manually
            </label>

            {isNewBatch && (
              <div className="mt-3 space-y-3">
                <input
                  type="text"
                  placeholder="Batch Number"
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                  value={batchInfo.batchNumber}
                  onChange={(e) => setBatchInfo({ ...batchInfo, batchNumber: e.target.value.toUpperCase() })}
                />
                <div>
                  <label className="block text-xs text-slate-500 mb-1">Expiry Date (optional)</label>
                  <input
                    type="date"
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                    value={batchInfo.expiryDate || ''}
                    onChange={(e) => setBatchInfo({ ...batchInfo, expiryDate: e.target.value })}
                  />
                </div>
                {batchInfo.expiryDate && new Date(batchInfo.expiryDate) < new Date() && (
                  <p className="text-sm text-red-600 flex items-center gap-1">
                    This batch is already expired
                  </p>
                )}
              </div>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700">Quantity</label>
            <input
              type="number"
              min="1"
              max={maxQty}
              className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm mt-1"
              value={batchInfo.quantity}
              onChange={(e) => setBatchInfo({ ...batchInfo, quantity: parseInt(e.target.value) || 1 })}
            />
            {batchInfo.quantity > maxQty && (
              <p className="text-xs text-red-600 mt-1">Maximum available: {maxQty}</p>
            )}
          </div>
        </div>

        <div className="px-5 py-4 border-t border-slate-200 bg-slate-50 rounded-b-2xl flex justify-end gap-3">
          <button
            onClick={onClose}
            className="px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-200 rounded-lg"
          >
            Cancel
          </button>
          <button
            onClick={() => onAdd(batchInfo.expiryDate)}
            disabled={!batchInfo.batchNumber || batchInfo.quantity < 1 || batchInfo.quantity > maxQty}
            className="px-4 py-2 text-sm font-medium bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Add to Cart
          </button>
        </div>
      </div>
    </div>
  );
};

// ==================== MANUAL ITEM MODAL ====================
const ManualItemModal: React.FC<{
  isOpen: boolean;
  onClose: () => void;
  onAdd: (name: string, price: number, quantity: number, gstRate: number, primaryUnit?: { id: string; name: string; symbol: string }, secondaryUnit?: { id: string; name: string; symbol: string }, conversionFactor?: number) => void;
  form: { name: string; price: number; quantity: number; gstRate: number; primaryUnitId: string; secondaryUnitId: string; conversionFactor: number };
  setForm: React.Dispatch<React.SetStateAction<{ name: string; price: number; quantity: number; gstRate: number; primaryUnitId: string; secondaryUnitId: string; conversionFactor: number }>>;
}> = ({ isOpen, onClose, onAdd, form, setForm }) => {
  const [customGst, setCustomGst] = useState<string>('');
  const [isCustomGst, setIsCustomGst] = useState(false);
  const { data: units = [] } = useUnitTypes();

  if (!isOpen) return null;

  const selectedPrimaryUnit = units.find(u => u.id === form.primaryUnitId);
  const selectedSecondaryUnit = units.find(u => u.id === form.secondaryUnitId);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.name.trim() || form.price <= 0 || form.quantity <= 0) return;
    const gstRate = isCustomGst ? parseFloat(customGst) || 0 : form.gstRate;
    onAdd(
      form.name,
      form.price,
      form.quantity,
      gstRate,
      selectedPrimaryUnit ? { id: selectedPrimaryUnit.id, name: selectedPrimaryUnit.name, symbol: selectedPrimaryUnit.symbol } : undefined,
      form.secondaryUnitId && selectedSecondaryUnit ? { id: selectedSecondaryUnit.id, name: selectedSecondaryUnit.name, symbol: selectedSecondaryUnit.symbol } : undefined,
      form.conversionFactor > 0 ? form.conversionFactor : undefined
    );
  };

  const handleGstSelect = (value: string) => {
    if (value === 'custom') {
      setIsCustomGst(true);
      setCustomGst('');
    } else {
      setIsCustomGst(false);
      setForm({ ...form, gstRate: parseFloat(value) });
    }
  };

  const currentGstRate = isCustomGst ? (parseFloat(customGst) || 0) : form.gstRate;

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-md overflow-hidden">
        <div className="px-5 py-4 border-b border-slate-200 bg-gradient-to-r from-amber-50 to-orange-50">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-amber-100 rounded-lg">
              <Plus size={20} className="text-amber-600" />
            </div>
            <div>
              <h3 className="text-lg font-semibold text-slate-900">Add Manual Item</h3>
              <p className="text-xs text-slate-500">Add a custom item not in your product database</p>
            </div>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-5 space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Item Name *</label>
            <input
              type="text"
              value={form.name}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
              placeholder="e.g., Custom Service, Gift Wrap, etc."
              className="w-full px-3 py-2.5 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-amber-500 focus:border-amber-500"
              required
              autoFocus
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Price (₹) *</label>
              <input
                type="number"
                min="0.01"
                step="0.01"
                value={form.price || ''}
                onChange={(e) => setForm({ ...form, price: parseFloat(e.target.value) || 0 })}
                placeholder="0.00"
                className="w-full px-3 py-2.5 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-amber-500 focus:border-amber-500"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Quantity *</label>
              <input
                type="number"
                min="1"
                value={form.quantity}
                onChange={(e) => setForm({ ...form, quantity: parseInt(e.target.value) || 1 })}
                className="w-full px-3 py-2.5 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-amber-500 focus:border-amber-500"
                required
              />
            </div>
          </div>

          {/* Unit Selection */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Primary Unit (selling)</label>
              <select
                value={form.primaryUnitId}
                onChange={(e) => setForm({ ...form, primaryUnitId: e.target.value })}
                className="w-full px-3 py-2.5 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-amber-500 focus:border-amber-500"
              >
                <option value="">-- Select --</option>
                {units.map((unit) => (
                  <option key={unit.id} value={unit.id}>
                    {unit.name} ({unit.symbol})
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Secondary Unit (optional)</label>
              <select
                value={form.secondaryUnitId}
                onChange={(e) => setForm({ ...form, secondaryUnitId: e.target.value, conversionFactor: 1 })}
                className="w-full px-3 py-2.5 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-amber-500 focus:border-amber-500"
              >
                <option value="">-- None --</option>
                {units.filter(u => u.id !== form.primaryUnitId).map((unit) => (
                  <option key={unit.id} value={unit.id}>
                    {unit.name} ({unit.symbol})
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Conversion Rate */}
          {form.secondaryUnitId && selectedSecondaryUnit && selectedPrimaryUnit && (
            <div className="p-3 bg-amber-50 border border-amber-200 rounded-lg">
              <label className="block text-sm font-semibold text-slate-700 mb-2">
                Conversion Rate
              </label>

              {/* Main Conversion */}
              <div className="flex items-center justify-center gap-2 bg-white p-3 rounded-lg border border-amber-300 shadow-sm mb-2">
                <span>1 {selectedSecondaryUnit.symbol}</span>
                <span>=</span>

                <input
                  type="number"
                  step="0.01"
                  min="0"
                  value={form.conversionFactor || ""}
                  onChange={(e) =>
                    setForm({
                      ...form,
                      conversionFactor: parseFloat(e.target.value) || 0,
                    })
                  }
                  placeholder="e.g. 10"
                  className="w-24 px-2 py-1 text-center border border-amber-300 rounded-md focus:outline-none focus:ring-2 focus:ring-amber-400"
                />

                <span>{selectedPrimaryUnit.symbol}</span>
              </div>

              {/* Reverse Conversion */}
              <div className="flex items-center justify-center gap-2 text-sm text-slate-500">
                <span>Reverse:</span>
                <span>1 {selectedPrimaryUnit.symbol}</span>
                <span>=</span>
                <span className="font-semibold text-amber-700">
                  {form.conversionFactor > 0
                    ? (1 / form.conversionFactor).toFixed(4)
                    : "0.0000"}{" "}
                  {selectedSecondaryUnit.symbol}
                </span>
              </div>

              {/* Preview */}
              <div className="mt-3 pt-3 border-t border-amber-200 text-center">
                <p className="text-sm font-medium text-amber-800">
                  1 {selectedSecondaryUnit.name} ={" "}
                  {form.conversionFactor || 0} {selectedPrimaryUnit.name}
                </p>

                <p className="text-xs text-amber-600 mt-1">
                  1 {selectedPrimaryUnit.name} ={" "}
                  {form.conversionFactor > 0
                    ? (1 / form.conversionFactor).toFixed(4)
                    : "0.0000"}{" "}
                  {selectedSecondaryUnit.name}
                </p>
              </div>
            </div>
          )}

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">GST Rate (%)</label>
            <div className="flex gap-2">
              <select
                value={isCustomGst ? 'custom' : form.gstRate}
                onChange={(e) => handleGstSelect(e.target.value)}
                className={isCustomGst ? "w-32 px-3 py-2.5 border border-slate-300 rounded-l-lg text-sm bg-slate-50" : "flex-1 px-3 py-2.5 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-amber-500 focus:border-amber-500"}
              >
                <option value={0}>No GST (0%)</option>
                <option value={5}>5%</option>
                <option value={12}>12%</option>
                <option value={18}>18%</option>
                <option value={28}>28%</option>
                <option value="custom">Custom...</option>
              </select>
              {isCustomGst && (
                <div className="flex-1">
                  <input
                    type="number"
                    min="0"
                    max="100"
                    step="0.1"
                    value={customGst}
                    onChange={(e) => setCustomGst(e.target.value)}
                    className="w-full px-3 py-2.5 border border-amber-400 border-l-0 rounded-r-lg text-sm focus:ring-2 focus:ring-amber-500 focus:border-amber-500"
                    placeholder="Enter custom %"
                    autoFocus
                  />
                </div>
              )}
            </div>
            {isCustomGst && customGst && (
              <p className="text-xs text-amber-600 mt-1">Custom GST rate: {customGst}%</p>
            )}
          </div>

          {/* Preview */}
          <div className="p-3 bg-slate-50 rounded-lg border border-slate-200 space-y-2">
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-600">Subtotal:</span>
              <span className="text-slate-900">
                ₹{(form.price * form.quantity).toFixed(2)}
              </span>
            </div>
            {currentGstRate > 0 && (
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-600">GST ({currentGstRate}%):</span>
                <span className="text-slate-900">
                  ₹{((form.price * form.quantity * currentGstRate) / 100).toFixed(2)}
                </span>
              </div>
            )}
            <div className="flex justify-between items-center text-sm pt-2 border-t border-slate-200">
              <span className="font-medium text-slate-700">Total (incl. GST):</span>
              <span className="font-semibold text-slate-900">
                ₹{(form.price * form.quantity * (1 + currentGstRate / 100)).toFixed(2)}
              </span>
            </div>
          </div>

          <div className="flex justify-end gap-3 pt-3 border-t border-slate-200">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={!form.name.trim() || form.price <= 0 || form.quantity <= 0}
              className="px-4 py-2 text-sm font-medium bg-amber-500 text-white rounded-lg hover:bg-amber-600 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
            >
              <Plus size={16} />
              Add to Cart
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Billing;

