import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useRef } from 'react';
import { bundleApi, BundlePayload, ApplicableBundle, BundleApplyResult } from '../services/apiClient/bundleApi';

export const useBundles = (filters?: { is_active?: boolean | string }) => {
  return useQuery({
    queryKey: ['bundles', filters],
    queryFn: () => bundleApi.getBundles(filters),
  });
};

export const useBundle = (id: string) => {
  return useQuery({
    queryKey: ['bundle', id],
    queryFn: () => bundleApi.getBundle(id),
    enabled: !!id,
  });
};

export const useCreateBundle = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (payload: BundlePayload) => bundleApi.createBundle(payload),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['bundles'] });
    },
  });
};

export const useUpdateBundle = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ id, payload }: { id: string; payload: Partial<BundlePayload> }) =>
      bundleApi.updateBundle(id, payload as BundlePayload),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['bundles'] });
    },
  });
};

export const useUpdateBundleItems = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ id, items }: { id: string; items: BundlePayload['items'] }) =>
      bundleApi.updateBundleItems(id, items),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['bundles'] });
    },
  });
};

export const useDeleteBundle = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => bundleApi.deleteBundle(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['bundles'] });
    },
  });
};

export const useDetectBundles = () => {
  // Debounce guard: avoid calling detectBundles when cart content hasn't changed
  const lastCartHash = useRef<string>('');
  return useMutation({
    mutationFn: (
      cartItems: {
        productId: string;
        variantId?: string;
        quantity: number;
        unitPrice: number;
      }[]
    ) => {
      const hash = cartItems
        .map((ci) => `${ci.productId}:${ci.variantId ?? ''}:${ci.quantity}:${ci.unitPrice}`)
        .join('|');
      if (hash === lastCartHash.current) {
        // No change since last detection; short-circuit with empty result
        return Promise.resolve({ data: [] } as any);
      }
      lastCartHash.current = hash;
      return bundleApi.detectBundles(cartItems);
    },
  });
};

export const useApplyBundle = () => {
  return useMutation({
    mutationFn: ({
      bundleId,
      cartItems,
      times,
    }: {
      bundleId: string;
      cartItems: { cartItemId: string; productId: string; variantId?: string; quantity: number; unitPrice: number }[];
      times?: number;
    }) => bundleApi.applyBundle(bundleId, cartItems, times),
  });
};
